package in.recallradar;
import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
@Service @Transactional class RecallService {private final RecallCaseRepository cases;private final RecallImpactSnapshotRepository snapshots;private final InventoryLotRepository lots;private final IngredientRepository ingredients;private final SupplierRepository suppliers;private final StockMovementRepository movements;private final InventoryBalanceRepository balances;private final ProductionConsumptionRepository consumptions;private final ProductionBatchRepository batches;private final RecipeRepository recipes;private final FinishedProductRepository products;private final LocationRepository locations;private final TenantService tenants;private final AuditService audit;
RecallService(RecallCaseRepository c,RecallImpactSnapshotRepository s,InventoryLotRepository l,IngredientRepository i,SupplierRepository sup,StockMovementRepository sm,InventoryBalanceRepository ib,ProductionConsumptionRepository pc,ProductionBatchRepository pb,RecipeRepository r,FinishedProductRepository p,LocationRepository lo,TenantService t,AuditService a){cases=c;snapshots=s;lots=l;ingredients=i;suppliers=sup;movements=sm;balances=ib;consumptions=pc;batches=pb;recipes=r;products=p;locations=lo;tenants=t;audit=a;}
List<RecallResponse> list(Membership m){return cases.findByOrganizationIdOrderByCreatedAtDesc(m.organizationId).stream().map(x->response(m,x)).toList();}
RecallResponse create(Membership m,RecallRequest request){tenants.requireMasterDataEditor(m);var lot=lots.findByIdAndOrganizationId(request.sourceLotId(),m.organizationId).orElseThrow(()->missing("Source lot"));var recall=cases.save(new RecallCase(m.organizationId,lot.id,request.title().trim(),m.userId));for(var consumption:consumptions.findByLotId(lot.id)){var batch=batches.findById(consumption.productionBatchId).orElseThrow();if(!batch.organizationId.equals(m.organizationId))continue;var recipe=recipes.findByIdAndOrganizationId(batch.recipeId,m.organizationId).orElseThrow();var product=products.findByIdAndOrganizationId(recipe.productId,m.organizationId).orElseThrow();snapshots.save(new RecallImpactSnapshot(recall.id,batch.id,batch.locationId,product.name,batch.batchNumber,batch.outputQuantity));}audit.record(m,"RECALL_CREATED","RECALL_CASE",recall.id,recall.title);return response(m,recall);}
RecallResponse status(Membership m,UUID id,RecallStatusRequest request){tenants.requireMasterDataEditor(m);var recall=cases.findByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->missing("Recall"));recall.status=request.status();audit.record(m,"RECALL_STATUS_UPDATED","RECALL_CASE",recall.id,request.status().name());return response(m,recall);}
RecallImpactAnalysisResponse impact(Membership m,UUID id){var recall=cases.findByIdAndOrganizationId(id,m.organizationId).orElseThrow(()->missing("Recall"));var lot=lots.findByIdAndOrganizationId(recall.sourceLotId,m.organizationId).orElseThrow(()->missing("Source lot"));var ingredient=ingredients.findByIdAndOrganizationId(lot.ingredientId,m.organizationId).orElseThrow();var supplier=tenantsSupplier(m,lot.supplierId);var ledger=lotLedger(lot.id);BigDecimal received=sum(ledger,MovementType.RECEIPT);BigDecimal consumed=sum(ledger,MovementType.PRODUCTION_CONSUMPTION);BigDecimal wasted=sum(ledger,MovementType.WASTE).add(sum(ledger,MovementType.DISPOSAL));BigDecimal adjustedIn=ledger.stream().filter(x->x.movementType==MovementType.ADJUSTMENT&&x.toLocationId!=null).map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal adjustedOut=ledger.stream().filter(x->x.movementType==MovementType.ADJUSTMENT&&x.fromLocationId!=null).map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal held=currentBalance(lot.id);BigDecimal unaccounted=received.add(adjustedIn).subtract(adjustedOut).subtract(held).subtract(consumed).subtract(wasted);var accounting=new RecallAccountingResponse(received,held,consumed,wasted,adjustedIn,adjustedOut,unaccounted,lot.unit);var movements=ledger.stream().map(x->new RecallMovementEvidenceResponse(x.id.toString(),x.movementType.name(),x.quantity,x.fromLocationId==null?null:locationName(m,x.fromLocationId),x.toLocationId==null?null:locationName(m,x.toLocationId),x.note,x.occurredAt)).toList();var trace=consumptions.findByLotId(lot.id).stream().map(x->{var batch=batches.findById(x.productionBatchId).orElseThrow();if(!batch.organizationId.equals(m.organizationId))throw missing("Production batch");var recipe=recipes.findByIdAndOrganizationId(batch.recipeId,m.organizationId).orElseThrow();var product=products.findByIdAndOrganizationId(recipe.productId,m.organizationId).orElseThrow();return new RecallProductionTraceResponse(batch.id.toString(),batch.batchNumber,product.name,x.quantity,x.unit,batch.outputQuantity,batch.outputUnit,locationName(m,batch.locationId),batch.producedAt);}).sorted(Comparator.comparing(RecallProductionTraceResponse::producedAt).reversed()).toList();return new RecallImpactAnalysisResponse(recall.id.toString(),recall.title,recall.status,lot.id.toString(),ingredient.name,supplier.name,lot.supplierBatchNumber,accounting,movements,trace,Instant.now());}
private List<StockMovement> lotLedger(UUID lotId){return movements.findByLotIdOrderByOccurredAt(lotId);}private BigDecimal sum(List<StockMovement> ledger,MovementType type){return ledger.stream().filter(x->x.movementType==type).map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);}private BigDecimal currentBalance(UUID lotId){return balances.findByLotId(lotId).stream().map(x->x.quantity).reduce(BigDecimal.ZERO,BigDecimal::add);}private String locationName(Membership m,UUID id){return locations.findByIdAndOrganizationId(id,m.organizationId).map(x->x.name).orElse("Unknown location");}private Supplier tenantsSupplier(Membership m,UUID id){return suppliers.findByIdAndOrganizationId(id,m.organizationId).orElseThrow();}
private RecallResponse response(Membership m,RecallCase recall){var lot=lots.findByIdAndOrganizationId(recall.sourceLotId,m.organizationId).orElseThrow();var ingredient=ingredients.findByIdAndOrganizationId(lot.ingredientId,m.organizationId).orElseThrow();var impacts=snapshots.findByRecallCaseId(recall.id).stream().map(x->{var location=locations.findByIdAndOrganizationId(x.locationId,m.organizationId).orElseThrow();return new RecallImpactResponse(x.productionBatchId.toString(),x.batchNumber,x.productName,location.name,x.affectedQuantity,"units");}).toList();return new RecallResponse(recall.id.toString(),recall.title,recall.status,lot.id.toString(),ingredient.name,lot.supplierBatchNumber,recall.createdAt,impacts);}
private ResponseStatusException missing(String s){return new ResponseStatusException(HttpStatus.NOT_FOUND,s+" not found.");}}
